const games={tower:{name:'Vial Tower',subtitle:'One tap. A little balance. A new personal best.',description:'Find your balance, one vial at a time.',tags:['One tap','Endless'],steps:['Watch the vial drift from side to side.','Tap or press Space to drop it onto the stack.','Land near the centre. Perfect drops earn bonus points.'],tip:'Take your time. A centred stack is a steady stack.',control:'Drop vial'},merge:{name:'Vial Merge',subtitle:'Small matches. Satisfying little chain reactions.',description:'Little matches. Lovely chain reactions.',tags:['Merge','Relaxing'],steps:['Move your pointer or drag to choose a spot.','Release your drag or press Space to drop it.','Match identical colours and numbers to make a bigger vial. Keep the pile below the line.'],tip:'Build pairs low in the jar and leave space for bigger vials.',control:'Drop vial'},sort:{name:'Lab Sort',subtitle:'A colourful puzzle, at your own pace.',description:'A little order. A lot of satisfaction.',tags:['Puzzle','No timer'],steps:['Select a tube, then select where to pour.','Pour onto the same colour, or into an empty tube.','Fill each tube with one colour. Undo and hints are always available.'],tip:'Empty tubes are breathing room. Use them to free a colour.',control:'Select a tube'},blocks:{name:'Peak Blocks',subtitle:'A fresh fit. A satisfying blast.',description:'Fit pieces, clear lines, keep your crystal board open.',tags:['Puzzle','Block blast'],steps:['Drag a piece from the tray onto the board, or tap it to select.','Fill a row or column to clear it. The highlighted squares show where your piece will land.','No pieces fit? The highlighted tools can help. Drag Bomb over the board to clear a 3 × 3 area; Undo restores a move, Shuffle replaces your hand, and Hint shows a fit.'],tip:'Keep space for the bigger pieces. The glowing preview shows a valid fit.',control:'Place a piece'},mahjong:{name:'Bottle Mahjong',subtitle:'Find a pair. Reveal a little more of the garden.',description:'Match open pairs in a layered bottle puzzle.',tags:['Puzzle','Pair match'],steps:['Choose a tile with nothing on top and at least one open side.','Tap an identical open tile to remove the pair.','Clear every pair. Hint, Undo and Shuffle each have 3 uses per board.'],tip:'Hints choose a pair that keeps a route to the finish.',control:'Match a pair'},orbit:{name:'Orbit',subtitle:'One clean launch. Then keep your rhythm.',description:'Pull, aim and release a ball into a glowing hoop.',tags:['Precision','Endless'],steps:['Pull the ball down and sideways, then release to shoot.','Use the dotted arc to aim. The ball must fall into the hoop from above.','You have three misses. The hoop moves faster and narrows as you score. Arrow keys aim; Space shoots.'],tip:'A longer pull gives more height. Small sideways adjustments go a long way.',control:'Release ball'},ridge:{name:'Ridge Run',subtitle:'Thread the gates. Keep your crystal airborne.',description:'Flap through the mountain course and set a new best.',tags:['Reflex','Endless'],steps:['Tap anywhere or press Space to lift your round crystal. Its edge is its hitbox.','Fly between bottle caps. The bottles reach the top and bottom edges.','Every 50 gates unlocks a new colour, faster flight and tighter openings. One free revive with a short shield is available per run.'],tip:'Short taps are easier to correct between gates.',control:'Flap'},bond:{name:'Bond',subtitle:'A steady ring. A very careful launch.',description:'Attach vials to the moving ring without a collision.',tags:['Timing','Endless'],steps:['Tap anywhere or press Space to send a vial toward the rotating ring.','It joins the ring when it does not hit another bottle.','The ring turns faster with each safe bond.'],tip:'Wait for a clean gap before you fire.',control:'Fire bond'},sequence:{name:'Sequence',subtitle:'Line up crystals and reach the level goal.',description:'Match three or more crystals before your moves run out.',tags:['Match 3','Levels'],steps:['Select or drag a crystal to swap it with a neighbour.','Try any neighbouring swap. Crystals return if there is no match, without using a move.','Complete the large goals above the board before your moves run out. Match 4 for a line blast, or 5 for a colour bomb.'],tip:'Ice: match on or beside it; each visible rim takes one hit. Locks: match beside the padlock to release its crystal. Match the requested colour to collect it.',control:'Select crystal'}};
