const badges=[{id:'first',name:'A fresh start',text:'Complete your first game.',symbol:'leaf'},{id:'tower10',name:'Peak performer',text:'Stack 10 vials in one run.',symbol:'trophy'},{id:'perfect5',name:'Perfectly placed',text:'Make 5 perfect drops.',symbol:'spark'},{id:'merge5',name:'Mixing magic',text:'Create a tier 5 vial.',symbol:'star'},{id:'sort1',name:'Clear mind',text:'Complete a Lab Sort level.',symbol:'check'},{id:'daily',name:'Daily delight',text:'Complete a daily challenge.',symbol:'flag'}];
function save(){try{localStorage.setItem('ph-arcade-v1',JSON.stringify(data));}catch{toast('Progress could not be saved. You can still keep playing.');}}
// Competition runs: the arcade page (our parent frame) starts the run on the server and leaves its seed in
// window.phRankedRun. While one is active the game uses that seed and level, and offers no paid retry.
function rankedRun(id){try{const run=window.parent!==window?window.parent.phRankedRun:null;return run&&run.game===id&&!run.done?run:null;}catch{return null;}}
// After a Sequence level is cleared, the next board's seed arrives once the server has verified the level.
async function rankedNextLevel(id,level){for(let i=0;i<150;i++){let run=null;try{run=window.parent.phRankedRun;}catch{}if(!run||run.game!==id||run.done||run.error)return false;if(!run.pending&&run.level===level)return true;await new Promise(r=>setTimeout(r,100));}return false;}
// The arcade page reports each verified result; the open result screen listens, otherwise it shows as a toast.
let rankedState=null,rankedSessionId=null;const rankedListeners=new Set();
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==window.parent||e.data?.type!=='ph-ranked-result'||e.data.runId!==rankedSessionId)return;if(e.data.state){rankedState=e.data.state;rankedListeners.forEach(fn=>fn(rankedState));}if(e.data.text&&!rankedListeners.size)toast(e.data.text);});
function rankedResults(id,level){return {subscribe(fn){rankedListeners.add(fn);fn(rankedState||{phase:'checking'});return()=>rankedListeners.delete(fn);},close(){rankedListeners.clear();},
 retry(){window.parent.postMessage({type:'ph-retry-result',game:id},location.origin);},
 playAgain(){rankedListeners.clear();window.parent.postMessage({type:'ph-play-again',game:id},location.origin);},
 async nextLevel(){rankedListeners.clear();if(await rankedNextLevel(id,level+1))beginGame(id,level+1);else{toast('This run could not continue. Your verified score still counts.');route('freeplay');}}};}
// Phone haptics. Android vibrates; on iPhone, Safari has no vibration API, but toggling a hidden switch control gives
// a light system tap (iOS 18 and later), which is used for the same moments. Off with the Vibration setting.
const HAPTICS={select:[5],undo:[6],drop:[8],crystal:[12],bond:[12],perfect:[20],merge:[28],invalid:[10,40,10],miss:[35,45,35],win:[18,60,30],combo2:[16,20,24],combo3:[18,24,36]};
let hapticAt=0,hapticSwitch=null;
function haptic(type,force=false){const pattern=active==='ridge'&&type==='perfect'?[8]:HAPTICS[type];// every Ridge gate is a lighter tick
 if(!pattern||data.haptics===false)return;const now=performance.now();if(!force&&now-hapticAt<45)return;hapticAt=now;
 try{if(navigator.vibrate){navigator.vibrate(pattern);return;}
  if(!hapticSwitch){const label=document.createElement('label');label.setAttribute('aria-hidden','true');label.style.cssText='position:fixed;left:-9999px;top:0;width:1px;height:1px;overflow:hidden';label.innerHTML='<input type="checkbox" switch tabindex="-1">';document.body.append(label);hapticSwitch=label;}
  hapticSwitch.click();}catch{/* Haptics are optional. */}}

// First-play hints: until a player has touched their way through two of them per game, a marker shows the opening
// gesture (drag a piece, swap two crystals, tap to fly). It waits for that first touch and never affects play.
const HINT_GAMES={blocks:'Drag a piece onto the board',sequence:'Swipe a crystal to swap it',ridge:'Tap anywhere to fly'},HINT_RUNS=2;
let hintCleanup=null;
function clearHint(){hintCleanup?.();hintCleanup=null;}
// A static arrow from where the gesture starts to where it ends, used when motion is reduced and the marker cannot travel.
function hintArrow(from,to){
 const dx=to[0]-from[0],dy=to[1]-from[1],len=Math.hypot(dx,dy);if(len<28)return null;
 const ang=Math.atan2(dy,dx),gap=Math.min(38,len*.3),head=Math.min(19,len*.28),half=Math.max(6,head*.55);
 const sx=from[0]+Math.cos(ang)*gap,sy=from[1]+Math.sin(ang)*gap,tx=to[0]-Math.cos(ang)*4,ty=to[1]-Math.sin(ang)*4;
 const bx=tx-Math.cos(ang)*head,by=ty-Math.sin(ang)*head,px=-Math.sin(ang)*half,py=Math.cos(ang)*half;
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),line=document.createElementNS(ns,'line'),tip=document.createElementNS(ns,'polygon');
 svg.setAttribute('class','hint-arrow');svg.setAttribute('aria-hidden','true');
 line.setAttribute('x1',sx);line.setAttribute('y1',sy);line.setAttribute('x2',bx);line.setAttribute('y2',by);
 tip.setAttribute('points',`${tx},${ty} ${bx+px},${by+py} ${bx-px},${by-py}`);
 svg.append(line,tip);return svg;
}
function showFirstPlayHint(id){
 clearHint();if(!HINT_GAMES[id]||!engine)return;
 data.hintRuns=data.hintRuns&&typeof data.hintRuns==='object'?data.hintRuns:{};if((data.hintRuns[id]||0)>=HINT_RUNS)return;
 const world=$('.game-world');if(!world)return;
 const wr=world.getBoundingClientRect(),pt=(x,y)=>[x-wr.left,y-wr.top];let from,to=null;
 if(id==='blocks'){const slot=world.querySelector('[data-shape]:not([disabled])'),board=$('#block-board');if(!slot||!board)return;const a=slot.getBoundingClientRect(),b=board.getBoundingClientRect();from=pt(a.left+a.width/2,a.top+a.height/2);to=pt(b.left+b.width/2,b.top+b.height/2);}
 else if(id==='sequence'){const pair=engine.findMove?.(),canvas=$('#game-canvas');if(!pair||!canvas||!engine.geometry)return;const g=engine.geometry(),r=canvas.getBoundingClientRect(),k=engine.scale,cell=i=>pt(r.left+(g.x+(i%7+.5)*g.cell)*k,r.top+(g.y+(Math.floor(i/7)+.5)*g.cell)*k);from=cell(pair[0]);to=cell(pair[1]);}
 else{const canvas=$('#game-canvas');if(!canvas)return;const r=canvas.getBoundingClientRect();from=pt(r.left+r.width*.5,r.top+r.height*.6);}
 const dot=document.createElement('div'),caption=document.createElement('div'),moving=motionAllowed();
 dot.className=moving?'hint-touch':'hint-touch hint-static';dot.setAttribute('aria-hidden','true');dot.style.left=`${from[0]}px`;dot.style.top=`${from[1]}px`;
 caption.className='hint-caption';caption.textContent=HINT_GAMES[id];caption.style.top=`${Math.max(84,from[1]-(id==='blocks'?92:70))}px`;
 world.append(dot,caption);
 const dx=to?to[0]-from[0]:0,dy=to?to[1]-from[1]:0,base='translate(-50%,-50%)';
 // Reduced motion: nothing travels, so a static arrow carries the direction and the marker fades in and out instead.
 const arrow=!moving&&to?hintArrow(from,to):null;if(arrow)world.append(arrow);
 const anim=!moving?dot.animate([{opacity:1},{opacity:.45,offset:.5},{opacity:1}],{duration:1700,iterations:Infinity,easing:'ease-in-out'})
  :to?dot.animate([{transform:`${base} scale(.8)`,opacity:0},{transform:`${base} scale(1)`,opacity:1,offset:.15},{transform:`${base} translate(${dx}px,${dy}px)`,opacity:1,offset:.7},{transform:`${base} translate(${dx}px,${dy}px)`,opacity:0}],{duration:1800,iterations:Infinity,easing:'ease-in-out'})
  :dot.animate([{transform:`${base} scale(1)`},{transform:`${base} scale(.75)`,offset:.25},{transform:`${base} scale(1)`}],{duration:900,iterations:Infinity});
 // A hint only counts once the player has actually touched the game while it was showing; it waits as long as that takes.
 const done=counted=>{if(counted){data.hintRuns[id]=(data.hintRuns[id]||0)+1;save();}anim?.cancel();dot.remove();caption.remove();arrow?.remove();world.removeEventListener('pointerdown',touched,true);if(hintCleanup===cleanup)hintCleanup=null;};
 const touched=()=>done(true),cleanup=()=>done(false);
 world.addEventListener('pointerdown',touched,true);hintCleanup=cleanup;
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function earn(id){if(data.badges.includes(id))return false;data.badges.push(id);return true;}
function streak(){let count=0,date=new Date();if(!data.days.includes(localDay(date)))date.setDate(date.getDate()-1);while(data.days.includes(localDay(date))){count++;date.setDate(date.getDate()-1);}return count;}
const gameAudio=new GameAudio(()=>data.sound);
document.addEventListener('pointerdown',()=>gameAudio.prepare(),{capture:true,passive:true});
document.addEventListener('keydown',()=>gameAudio.prepare(),{capture:true});
const soundCues={big:[0,4,7,12],sparkle:[12],drop:[0],select:[7],invalid:[0,-4],undo:[3,0],hint:[5,9],tool:[0,5],perfect:[0,7],merge:[0,4,7],win:[0,4,7,12,16],miss:[0,-3,-7],toggle:[7,12]};
function sound(type,opts){haptic(type);if(!data.sound)return;if(gameAudio.play(active,type,opts))return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume().catch(()=>{});const notes=soundCues[type]||soundCues.select,base={tower:440,merge:349,sort:554,blocks:392,mahjong:659,orbit:554,ridge:494,bond:440,sequence:740}[active]||440,wave=active==='merge'||active==='blocks'||active==='ridge'?'triangle':'sine',now=audio.currentTime;notes.forEach((step,index)=>{const oscillator=audio.createOscillator(),gain=audio.createGain(),start=now+index*.058,duration=type==='win'?0.17:0.12,frequency=base*2**(step/12);oscillator.type=wave;oscillator.frequency.setValueAtTime(frequency,start);oscillator.frequency.exponentialRampToValueAtTime(frequency*1.025,start+duration*.45);gain.gain.setValueAtTime(.0001,start);gain.gain.linearRampToValueAtTime(type==='win'?0.03:0.022,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start(start);oscillator.stop(start+duration+.02);});}catch{/* Audio is optional. */}}
function soundSettingControl(id){return '<label class="settings-row sound-setting-row"><div><strong>Game sound effects</strong><small></small></div><input id="'+id+'" type="checkbox" aria-label="Game sound effects" '+(data.sound?'checked':'')+'></label>';}
function bindSoundControl(id){const input=$('#'+id);if(!input)return;const small=input.closest('.settings-row')?.querySelector('small'),update=()=>{if(small)small.textContent=data.sound?'Sound effects on · tap to mute':'Sound effects off · tap to enable';};update();input.onchange=()=>{data.sound=input.checked;data.soundPreference=true;save();update();if(!data.sound){gameAudio.stop();audio?.suspend().catch(()=>{});}else sound('toggle');};}
function logo(){return `<img class="ph-logo" src="assets/ph-arcade-logo.webp" alt="PH Arcade">`;}
function currency(){return `<div class="player-pills"><button class="currency coin" data-wallet aria-label="${data.coins} coins. View rewards">${icon('coin')}<b>${fmt(data.coins)}</b><span>+</span></button><button class="currency gem" data-wallet aria-label="${data.gems} gems. View rewards">${icon('gem')}<b>${fmt(data.gems)}</b><span>+</span></button><button class="icon-button settings-button" data-settings aria-label="Open settings">${icon('settings')}</button></div>`;}
function shell(content,selected='home',world=selected){const scene=selected==='game'?`game-${world}`:world==='help'?'profile':world,format='webp',asset=['orbit','ridge','bond','sequence'].includes(world)?`${scene}-v2`:scene==='home'?'home-lobby':scene;document.body.classList.toggle('game-open',selected==='game');document.body.dataset.scene=scene;document.body.style.setProperty('--world-art',`url("assets/worlds/${asset}.${format}")`);app.innerHTML=`<div class="phone-app world-interface view-${selected} ${selected==='game'?'in-game':''}">${selected==='game'?'':`<header class="app-header"><a class="brand" href="#home" aria-label="PH Arcade home">${logo()}</a>${currency()}</header>`}<main>${content}</main>${selected==='game'?'':`<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['arcade','games','Arcade'],['journey','gift','Rewards'],['collection','bottle','Bottles'],['profile','user','Profile']].map(([id,s,label])=>`<button data-nav="${id}" class="${selected===id?'active':''}" ${selected===id?'aria-current="page"':''}>${icon(s)}<span>${label}</span></button>`).join('')}</nav>`}</div>`;document.body.classList.toggle('motion-off',!data.motion);syncSceneParallax();app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));app.querySelectorAll('[data-wallet]').forEach(b=>b.onclick=()=>navigate('journey'));$('[data-settings]')?.addEventListener('click',openSettings);$('.brand')?.addEventListener('click',e=>{e.preventDefault();navigate('home');});}

function gameArt(type){return `<div class="game-art cover-art cover-${type}" role="img" aria-label="${games[type].name} colourful 3D alpine game artwork"></div>`;}
const GAME_ICONS={tower:'merge.png',merge:'tower.png',sort:'sort.png',blocks:'blocks.png',mahjong:'mahjong.png',orbit:'orbit.png',ridge:'ridge.png',bond:'bond.png',sequence:'sequence.png'};
function gameIcon(type){return `<img class="game-icon" src="assets/game-icons/${GAME_ICONS[type]}" alt="" aria-hidden="true" decoding="async">`;}
function gameDisplay(id,{compact=false,kind=false}={}){const g=games[id];return `<button class="game-display ${compact?'compact':''}" data-play="${id}" ${kind?`data-kind="${puzzleGames.includes(id)||id==='blocks'?'puzzle':'casual'}"`:''} aria-label="Play ${g.name}"><span class="display-object">${gameIcon(id)}</span><span class="display-label"><b>${g.name}</b>${compact?'':`<small>${puzzleGames.includes(id)?`Level ${puzzleLevel(id)}`:`Best ${fmt(data.best[id])}`}</small>`}</span></button>`;}
function renderHome(){view='home';const nextPuzzle=puzzleLevel('sort'),done=Math.min(data.mergeDay===localDay()?data.mergeToday||0:0,10);shell(`<section class="home-hero scene-banner" aria-label="Peak Haven waterfall world"><h1 class="sr-only">Peak Haven Arcade</h1><div class="lobby-mascot" aria-hidden="true">${mascot()}</div></section><section class="home-content"><div class="category-tabs" aria-label="Choose game category"><button class="active" aria-pressed="true" data-category="all">${icon('games')}All Games</button><button aria-pressed="false" data-category="puzzle">${icon('leaf')}Puzzle</button><button aria-pressed="false" data-category="casual">${icon('star')}Casual</button></div><div class="section-heading world-heading"><h2>Your arcade</h2><button class="text-button" data-nav="freeplay">See all ${icon('arrow')}</button></div><div class="game-display-grid" aria-label="Popular games">${Object.keys(games).map(id=>gameDisplay(id,{compact:true,kind:true})).join('')}<button class="game-display reward-display" data-nav="journey" aria-label="Open daily rewards"><span class="display-object"><img src="assets/reward-chest.webp" alt="" aria-hidden="true"></span><span class="display-label"><b>Daily rewards</b></span></button></div><button class="daily-pick lab-console" data-play="merge"><span class="daily-copy"><h2>Merge 10 bottles</h2><p>${done>=10?'Complete! Collect your reward.':'Your daily challenge'}</p><span class="daily-progress"><i style="transform:scaleX(${done/10})"></i><b>${done} / 10</b></span></span><span class="daily-object">${gameIcon('merge')}</span>${icon('play')}</button><button class="next-mission lab-console slim-console" data-nav="arcade">${icon('flag')}<span><b>Continue a puzzle</b><small>Lab Sort · Level ${nextPuzzle}</small></span>${icon('arrow')}</button><p class="device-note">Progress saves on this device.</p></section>`,'home');bindPlay();app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{app.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});app.querySelectorAll('[data-kind]').forEach(x=>x.hidden=b.dataset.category!=='all'&&x.dataset.kind!==b.dataset.category);});}
let selectedPuzzle='sort',selectedPuzzleLevel=1,visiblePuzzleLevels=18;
const puzzleGames=['sort','mahjong','sequence'],endlessGames=['tower','merge','blocks','orbit','ridge','bond'];
const puzzleLevel=id=>Math.max(1,data.gameLevels[id]||1);
function renderArcade(){view='arcade';selectedPuzzleLevel=puzzleLevel(selectedPuzzle);visiblePuzzleLevels=Math.max(18,Math.ceil(selectedPuzzleLevel/12)*12+6);renderPuzzleLevels();}
function renderPuzzleLevels(){const id=selectedPuzzle,game=games[id],level=puzzleLevel(id),limit=Math.max(visiblePuzzleLevels,level+5);shell(`<section class="arcade-levels"><header class="levels-heading lab-console"><h1>Puzzle levels</h1><p>Clear each board to unlock the next. Challenges get tougher as you climb.</p></header><div class="level-game-tabs" role="tablist" aria-label="Choose a puzzle game">${puzzleGames.map(gameId=>`<button role="tab" aria-selected="${id===gameId}" class="${id===gameId?'active':''}" data-level-game="${gameId}" aria-controls="puzzle-level-panel">${gameIcon(gameId)}<span>${games[gameId].name}</span></button>`).join('')}</div><section class="puzzle-level-panel lab-console" id="puzzle-level-panel" role="tabpanel"><div class="puzzle-level-summary"><span class="level-game-icon">${gameIcon(id)}</span><div><h2>${game.name}</h2><p>Level ${level} ready · no timer</p></div><span class="level-count">${fmt(level-1)} cleared</span></div><div class="level-grid" aria-label="${game.name} levels">${Array.from({length:limit},(_,i)=>{const n=i+1,open=n<=level,done=n<level,selected=n===selectedPuzzleLevel;return `<button class="puzzle-level-node ${done?'complete':''} ${selected?'selected':''}" data-level="${n}" ${open?'':'disabled'} aria-label="${open?(done?'Replay':'Play'):'Locked'} ${game.name} level ${n}" aria-pressed="${selected}"><span>${done?icon('check'):n}</span>${selected?'<small>PLAY</small>':''}</button>`;}).join('')}</div><button class="text-button more-levels" id="more-levels">Show more levels ${icon('arrow')}</button><button class="button selected-level-play" id="play-selected-level">${icon('play')}Play level ${selectedPuzzleLevel}</button></section><div class="endless-heading world-heading"><div><h2>Endless runs</h2><p>Play for a new high score. The pace picks up as you go.</p></div></div><div class="endless-list">${endlessGames.map(gameId=>`<button class="endless-game lab-console slim-console" data-play="${gameId}"><span class="endless-game-icon">${gameIcon(gameId)}</span><span><b>${games[gameId].name}</b><small>Endless · Best ${fmt(data.best[gameId])}</small></span>${icon('play')}</button>`).join('')}</div><p class="device-note">Progress saves on this device.</p></section>`,'arcade');app.querySelectorAll('[data-level-game]').forEach(b=>b.onclick=()=>{selectedPuzzle=b.dataset.levelGame;selectedPuzzleLevel=puzzleLevel(selectedPuzzle);visiblePuzzleLevels=Math.max(18,Math.ceil(selectedPuzzleLevel/12)*12+6);renderPuzzleLevels();});app.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{selectedPuzzleLevel=Number(b.dataset.level);app.querySelectorAll('[data-level]').forEach(x=>{const n=Number(x.dataset.level);x.classList.toggle('selected',n===selectedPuzzleLevel);x.setAttribute('aria-pressed',String(n===selectedPuzzleLevel));});$('#play-selected-level').innerHTML=`${icon('play')}Play level ${selectedPuzzleLevel}`;});$('#more-levels').onclick=()=>{visiblePuzzleLevels+=12;renderPuzzleLevels();};$('#play-selected-level').onclick=()=>{if(selectedPuzzleLevel<=puzzleLevel(id))openGame(id,false,selectedPuzzleLevel);};bindPlay();}
function renderFreeplay(){view='freeplay';shell(`<section class="game-picker"><div class="subpage-heading lab-console"><h1>Choose your game</h1><p>A little balance, a perfect pair, a new record.</p></div><div class="game-display-grid picker-grid">${Object.keys(games).map(id=>gameDisplay(id)).join('')}</div><button class="button secondary" data-nav="arcade">${icon('flag')}Puzzle levels</button><p class="device-note">Lab Sort, Bottle Mahjong, and Sequence have levels.<br>Other games are endless runs.</p></section>`,'arcade');bindPlay();}
function levelProgress(){const level=Math.floor(data.xp/150)+1;return {level,current:data.xp%150,fraction:(data.xp%150)/150};}
function collectionTiles(compact=false){return SKINS.map((skin,i)=>{const owned=data.skins.includes(skin.id),available=skinUnlocked(data,skin);return `<button class="bottle-tile archive-display ${data.skin===skin.id?'equipped':''} ${owned?'owned':'locked'}" data-skin="${skin.id}" aria-label="${skin.name}. ${data.skin===skin.id?'Equipped':owned?'Equip':available?'Unlock':'Locked'}">${vial(i)}<span class="bottle-tile-state">${icon(owned?'check':available?'arrow':'lock')}</span>${compact?'':`<strong>${skin.name}</strong><small>${owned?(data.skin===skin.id?'Equipped':'Tap to equip'):skin.coins?`${skin.coins} coins`:skin.gems?`${skin.gems} gems`:skin.requirement}</small>`}</button>`;}).join('');}
function badgeTiles(){return badges.map((b,i)=>`<article class="badge-item ${data.badges.includes(b.id)?'':'locked'}"><div class="badge-icon badge-${i%4}">${icon(data.badges.includes(b.id)?b.symbol:'lock')}</div><h3>${b.name}</h3><p>${data.badges.includes(b.id)?'Unlocked!':b.text}</p></article>`).join('');}
function renderProfile(){view='profile';const lv=levelProgress();shell(`<section class="profile-backdrop scene-banner" aria-label="Your mountain observatory"><h1 class="sr-only">Profile</h1></section><section class="profile-sheet lab-console"><div class="profile-identity"><button class="avatar" data-nav="collection" aria-label="Customize your bottle">${mascot()}</button><div><h1>${escapeText(data.playerName)}</h1><div class="profile-level"><b>Lv ${lv.level}</b><div class="xp-track"><i style="transform:scaleX(${lv.fraction})"></i></div><span>${lv.current} / 150 XP</span></div><p>Collect. Customize. Play!</p></div><button class="icon-button edit-name" id="edit-name" aria-label="Edit player name">${icon('settings')}</button></div><div class="profile-stats">${[['flame',streak(),'DAY STREAK'],['games',data.games,'GAMES PLAYED'],['star',data.badges.length,'ACHIEVEMENTS'],['bottle',data.skins.length,'BOTTLES']].map(([s,n,l])=>`<div>${icon(s)}<b>${n}</b><span>${l}</span></div>`).join('')}</div></section><section class="content-module lab-console"><div class="section-heading"><h2>${icon('bottle')}MY BOTTLE COLLECTION</h2><button class="text-button" data-nav="collection">${data.skins.length} / 6 ${icon('arrow')}</button></div><div class="bottle-row">${collectionTiles(true)}</div></section><section class="content-module lab-console"><div class="section-heading"><h2>${icon('trophy')}ACHIEVEMENTS</h2><button class="text-button" data-nav="journey">${data.badges.length} / 6 ${icon('arrow')}</button></div><div class="badge-row">${badgeTiles()}</div></section><div class="profile-actions lab-console slim-console"><button id="profile-settings">${icon('settings')}Settings ${icon('arrow')}</button><button data-nav="collection">${icon('bottle')}Customize ${icon('arrow')}</button><button data-nav="help">${icon('help')}Help ${icon('arrow')}</button></div><p class="device-note">Saved on this device. Game currency has no cash value.</p>`,'profile');$('#profile-settings').onclick=openSettings;$('#edit-name').onclick=editName;bindCollection();bindPlay();}
function renderJourney(){view='journey';const lv=levelProgress(),ready=data.claimDay!==localDay();shell(`<section class="rewards-hero scene-banner" aria-label="Your golden reward treasury"><h1 class="sr-only">Rewards</h1></section><div class="rewards-content"><section class="progress-module lab-console"><div class="level-shield"><small>Lv</small><b>${lv.level}</b></div><div><h2>${fmt(data.xp)} XP</h2><div class="xp-track"><i style="transform:scaleX(${lv.fraction})"></i></div><p>${150-lv.current} XP to level ${lv.level+1}</p></div><button class="next-reward" data-nav="collection">${vial(1)}<span>MY BOTTLES<br><b>${data.skins.length} / 6</b></span></button></section><section class="streak-module lab-console"><div>${icon('flame')}<b>${streak()} ${streak()===1?'DAY':'DAYS'}</b><p>Play daily to keep your streak!</p></div><div class="streak-calendar">${Array.from({length:7},(_,i)=>`<span class="${i<Math.min(streak(),7)?'done':''}">${icon(i===6?'star':'check')}<small>DAY ${i+1}</small></span>`).join('')}</div></section><section class="daily-chest lab-console treasury-console"><div><h2>${ready?'Daily reward ready':'Your reward is claimed'}</h2><p>${ready?'Claim coins, gems, and bonus XP.':'Your next daily surprise is waiting for tomorrow.'}</p></div><img src="assets/reward-chest.webp" alt="Blue and silver reward chest"><button class="button gold-button" id="daily-open">${icon('gift')}${ready?'OPEN CHEST':'VIEW REWARD'}</button></section><section class="content-module reward-calendar lab-console treasury-console"><div class="section-heading"><h2>REWARD CALENDAR</h2><button class="text-button" id="spin-open">Lucky Spin ${icon('arrow')}</button></div><div class="calendar-row">${Array.from({length:5},(_,i)=>`<button data-reward-day="${i}" class="${i===0?'today':''}"><strong>${i===0?'TODAY':'DAY '+(i+1)}</strong>${i%2===0?vial(i===0?1:i):icon('gem')}<span>${icon('coin')}${50+i*10}</span></button>`).join('')}</div></section><div class="reward-bottom"><section class="content-module lab-console"><div class="section-heading"><h2>COLLECTIBLE BADGES</h2></div><div class="badge-row">${badgeTiles()}</div></section><section class="boost-module lab-console">${icon('spark')}<h2>2× Coins</h2><p>${data.boostRuns?`${data.boostRuns} games left`:'For your next 5 games'}</p><button class="button" id="boost-open">${data.boostRuns?'BOOST ACTIVE':'USE BOOST'}</button></section></div><p class="device-note">Rewards are in-game collectibles. No purchases required.</p></div>`,'journey');$('#daily-open').onclick=openDaily;$('#spin-open').onclick=openSpin;$('#boost-open').onclick=openBoost;app.querySelectorAll('[data-reward-day]').forEach(b=>b.onclick=()=>Number(b.dataset.rewardDay)===0?openDaily():toast(`Day ${Number(b.dataset.rewardDay)+1}: ${50+Number(b.dataset.rewardDay)*10} coins. Return on consecutive days to grow your daily reward.`));}
function renderCollection(){view='collection';const equipped=SKINS.find(s=>s.id===data.skin);shell(`<section class="collection-hero scene-banner" aria-label="The crystal bottle archive"><h1 class="sr-only">My bottles</h1></section><section class="collection-body"><div class="collection-current lab-console"><span class="equipped-display">${vial(SKINS.findIndex(s=>s.id===data.skin))}</span><div><h1>${equipped.name}</h1><p>Equipped for Vial Tower</p><span class="equipped-label">${icon('check')}Equipped</span></div></div><div class="section-heading world-heading"><h2>Bottle archive</h2><span>${data.skins.length} / 6 owned</span></div><div class="collection-grid">${collectionTiles()}</div><button class="button" data-nav="journey">${icon('gift')}Earn more rewards</button><p class="device-note">Earn currency through play.<br>No real-money purchases.</p></section>`,'collection');bindCollection();}
function bindCollection(){app.querySelectorAll('[data-skin]').forEach(b=>b.onclick=()=>openBottle(b.dataset.skin));}
function openBottle(id){const skin=SKINS.find(s=>s.id===id),i=SKINS.indexOf(skin),owned=data.skins.includes(id),available=skinUnlocked(data,skin);showModal(`<button class="icon-button close" id="modal-close" aria-label="Close bottle">${icon('close')}</button><div class="bottle-reveal">${vial(i)}</div><h2 id="dialog-title">${skin.name}</h2><p>${owned?'Make this bottle yours.':skin.requirement}</p><button class="button" id="bottle-action" ${!owned&&!available?'disabled':''}>${owned?(data.skin===id?'Equipped':'Equip bottle'):skin.coins?`Unlock · ${skin.coins} coins`:skin.gems?`Unlock · ${skin.gems} gems`:'Claim bottle'}</button>`);$('#modal-close').onclick=closeModal;$('#bottle-action').onclick=()=>{if(!owned){const bought=buySkin(data,id);if(!bought.ok){toast(bought.reason);return;}data=bought.data;}data.skin=id;save();closeModal();toast(`${skin.name} equipped!`);sound('perfect');if(view==='collection')renderCollection();else if(view==='profile')renderProfile();};}
function openDaily(){const ready=data.claimDay!==localDay();showModal(`<button class="icon-button close" id="modal-close" aria-label="Close daily reward">${icon('close')}</button><div class="chest-reveal"><img src="assets/reward-chest.webp" alt="Daily reward chest"></div><h2 id="dialog-title">${ready?'Your daily reward!':'Reward collected!'}</h2><p>${ready?'A little thank you for stopping by.':'Your chest opens again tomorrow.'}</p><div class="loot-row"><span>${icon('coin')}<b>${ready?dailyCoins():data.lastDailyCoins||50}</b>Coins</span><span>${icon('gem')}<b>+1</b>Gem</span><span>${icon('spark')}<b>+10</b>XP</span></div><button class="button gold-button" id="claim-daily">${ready?'Claim Reward':'Awesome!'}</button>`);$('#modal-close').onclick=closeModal;$('#claim-daily').onclick=()=>{if(ready){const result=claimDaily(data,localDay());if(result.ok){data=result.data;save();closeModal();refreshView();confetti();sound('win');toast('Reward claimed! Coins, gem and XP added.');}}else closeModal();};}
function dailyCoins(){return claimDaily(data,localDay()).coins||data.lastDailyCoins||50;}
function openSpin(){const ready=data.spinDay!==localDay();showModal(`<button class="icon-button close" id="modal-close" aria-label="Close lucky spin">${icon('close')}</button><div class="spin-wheel" id="spin-wheel">${[20,40,1,60,2,30].map((n,i)=>`<span style="--i:${i}">${n}${icon(i===2||i===4?'gem':'coin')}</span>`).join('')}</div><h2 id="dialog-title">A little lucky moment</h2><p>${ready?'One free spin a day. Just for fun.':'Your free spin returns tomorrow.'}</p><button class="button" id="spin-button" ${ready?'':'disabled'}>${ready?'Spin for free':'Already spun today'}</button><p class="modal-footnote">No payment, betting, or cash prizes.</p>`);$('#modal-close').onclick=closeModal;$('#spin-button').onclick=()=>{const result=claimSpin(data,localDay(),Math.random());if(!result.ok)return;data=result.data;save();$('#spin-button').disabled=true;$('#spin-wheel').animate([{transform:'rotate(0deg)'},{transform:`rotate(${1440+result.slot*60}deg)`}],{duration:motionAllowed()?1600:0,easing:'cubic-bezier(.12,.7,.2,1)',fill:'forwards'}).finished.then(()=>{if(!dialog.open||!$('#spin-button'))return;$('#dialog-title').textContent=`You won ${result.amount} ${result.currency}!`;$('#spin-button').textContent='Collect reward';$('#spin-button').disabled=false;$('#spin-button').onclick=()=>{closeModal();refreshView();confetti();};sound('win');});};}
function openBoost(){if(data.boostRuns){toast(`Your 2× coin boost is active for ${data.boostRuns} more games.`);return;}showModal(`<div class="modal-emblem">${icon('spark')}</div><h2 id="dialog-title">Double your game coins</h2><p>2× coins for your next 5 completed games.<br>Unlock with ${boostCost} in-game coins.</p><button class="button" id="boost-buy">Use ${boostCost} coins</button><button class="button secondary" id="boost-cancel">Maybe later</button>`);$('#boost-cancel').onclick=closeModal;$('#boost-buy').onclick=()=>{if(data.coins<boostCost){toast('Play a game or open your daily chest to earn more coins.');return;}data.coins-=boostCost;data.boostRuns=5;save();closeModal();refreshView();toast('2× coin boost activated!');};}
function editName(){showModal(`<h2 id="dialog-title">Your player name</h2><label class="name-label">Name<input id="player-name" maxlength="20" value="${escapeText(data.playerName)}" autocomplete="nickname"></label><button class="button" id="name-save">Save name</button><button class="button secondary" id="name-cancel">Cancel</button>`);$('#name-cancel').onclick=closeModal;$('#name-save').onclick=()=>{const name=$('#player-name').value.trim();if(!name){toast('Enter a player name to continue.');return;}data.playerName=name;save();closeModal();renderProfile();};}
function refreshView(){if(view==='journey')renderJourney();else if(view==='arcade')renderArcade();else if(view==='collection')renderCollection();else if(view==='profile')renderProfile();else renderHome();}
function renderHelp(id=helpGame){view='help';helpGame=id;shell(`<div class="view-title"><h1>Easy to learn. Lovely to play.</h1><p>A few simple steps, then you’re on your way.</p></div><div class="help-tabs" role="tablist" aria-label="Game instructions">${Object.entries(games).map(([k,g])=>`<button role="tab" aria-selected="${k===id}" class="${k===id?'active':''}" data-help-tab="${k}">${g.name}</button>`).join('')}</div><section class="help-content lab-console" role="tabpanel"><h2>${games[id].name}</h2><p>${games[id].subtitle}</p>${steps(id)}<div class="help-tip">${games[id].tip}</div><button class="button" data-play="${id}">${icon('play')}Let’s play</button></section>`,'help');app.querySelectorAll('[data-help-tab]').forEach(b=>b.onclick=()=>renderHelp(b.dataset.helpTab));bindPlay();}
function steps(id){return `<ol class="steps">${games[id].steps.map((s,i)=>`<li><span class="step-number">${i+1}</span><span>${s}</span></li>`).join('')}</ol>`;}
function bindPlay(){app.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{openGame(b.dataset.play);});app.querySelectorAll('[data-how]').forEach(b=>b.onclick=()=>navigate(`help/${b.dataset.how}`));}
function setHash(value){history.replaceState(null,'',`#${value}`);}
function navigate(destination){if(active){openLeave(destination);return;}route(destination);}
function route(destination='home'){if(window.parent!==window&&!destination.startsWith('play/')){stopGame();window.parent.postMessage({type:'ph-game-exit',game:document.body.dataset.scene?.replace('game-','')},location.origin);return;}stopGame();if(dialog.open)dialog.close();setHash(destination);window.scrollTo(0,0);if(destination==='arcade')renderArcade();else if(destination==='collection')renderCollection();else if(destination==='freeplay')renderFreeplay();else if(destination==='profile')renderProfile();else if(destination==='journey')renderJourney();else if(destination.startsWith('help'))renderHelp(destination.split('/')[1]||helpGame);else if(destination.startsWith('mission/'))renderArcade();else if(destination.startsWith('play/')){renderHome();openGame(destination.split('/')[1]);}else renderHome();}
function showModal(content,onCancel=()=>{}){if(dialog.open)dialog.close();modalReturn=document.activeElement;cancelModal=onCancel;dialog.innerHTML=`<div class="modal">${content}</div>`;dialog.showModal();}
function closeModal(){dialog.close();cancelModal=()=>{};if(modalReturn?.isConnected)modalReturn.focus();}
dialog.addEventListener('cancel',e=>{e.preventDefault();const cb=cancelModal;closeModal();cb();});
