// Peak Blocks sends the combo and line count with each clear (see blast() in puzzle-games.js), which sets how hard the
// board flashes and how strong the haptic is. The callout text itself comes from the game.
// Sequence's helper dock, wired the way Peak Blocks' is: a count on each button, the tools that can still
// help glowing when the board has nothing left, and the Hammer arming itself for the next tap on the board.
// The engine owns the rules, including what a tool may do and when, so this only draws and forwards.
function sequenceToolState(state){
 const assist=$('.sequence-assist');
 for(const [name,button] of Object.entries(sequenceToolButtons())){
  const left=state[name]??0;
  button.querySelector('b').textContent=left;
  button.disabled=left===0;
  button.classList.toggle('tool-suggested',state.stuck&&left>0);
  button.classList.toggle('active',name==='hammer'&&Boolean(state.armed));
  button.setAttribute('aria-pressed',String(name==='hammer'&&Boolean(state.armed)));
  button.setAttribute('aria-label',`${name[0].toUpperCase()+name.slice(1)}. ${left} uses left. ${name==='shuffle'?'Re-mix the board. It always leaves a move.':'Break one crystal. It counts toward the goals.'}`);
 }
 $('.game-world')?.classList.toggle('sequence-stuck',Boolean(state.stuck));
 if(!assist)return;
 assist.hidden=!state.stuck;
 if(state.stuck)assist.innerHTML='<strong>No moves? Use a tool</strong><span>Shuffle re-mixes the board. Hammer breaks one crystal.</span>';
}
function sequenceToolButtons(){
 return Object.fromEntries([...document.querySelectorAll('.game-tools [data-tool]')].map(b=>[b.dataset.tool,b]));
}
function bindSequenceTools(){
 const buttons=sequenceToolButtons();
 buttons.shuffle?.addEventListener('click',()=>{if(engine?.useShuffle?.())return;sound('invalid');});
 buttons.hammer?.addEventListener('click',()=>{if(!engine?.armHammer)return;if(engine.armHammer(!engine.hammerArmed))sound('tool');else sound('invalid');});
 sequenceToolState(engine?.toolState?.()??{shuffle:0,hammer:0});
}
function blockImpactFeedback(label,meta){
 if(!meta)return label;
 const board=$('#block-board'),big=meta.perfect||meta.newBest||meta.combo>=3||meta.lines>=3;
 if(board&&motionAllowed()){
  board.classList.remove('block-clearing','block-combo-2','block-combo-3');void board.offsetWidth;board.classList.add('block-clearing');
  if(meta.combo>1||meta.lines>1||meta.perfect)board.classList.add(big?'block-combo-3':'block-combo-2');
  setTimeout(()=>board.classList.remove('block-clearing','block-combo-2','block-combo-3'),520);
 }
 haptic(big?'combo3':'combo2',true);
 return label;
}
function impact(label,kind,meta){const el=$('#impact-label');if(!el)return;if(kind==='blocks')label=blockImpactFeedback(label,meta);el.textContent=label;el.className=`impact-label ${kind}`;if(motionAllowed()){el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:0,transform:'translateY(16px) scale(.65)'},{opacity:1,transform:'translateY(-8px) scale(1.12)',offset:.25},{opacity:1,transform:'translateY(-16px) scale(1)',offset:.65},{opacity:0,transform:'translateY(-44px) scale(1)'}],{duration:1000,easing:'cubic-bezier(.23,1,.32,1)'});$('.canvas-wrap')?.animate([{transform:'translateY(0)'},{transform:'translateY(3px)'},{transform:'translateY(0)'}],{duration:180});}else{el.style.opacity=1;setTimeout(()=>el.style.opacity=0,700);}}
function confetti(){if(!motionAllowed())return;const wrap=document.createElement('div');wrap.className='confetti';wrap.setAttribute('aria-hidden','true');app.append(wrap);for(let i=0;i<42;i++){const p=document.createElement('i');p.style.background=COLORS[i%6];p.style.left=`${Math.random()*100}%`;wrap.append(p);p.animate([{transform:`translateY(-30px) rotate(0deg)`,opacity:1},{transform:`translate(${(Math.random()-.5)*160}px, ${window.innerHeight+50}px) rotate(${Math.random()*720}deg)`,opacity:0}],{duration:1800+Math.random()*1000,delay:Math.random()*350,easing:'cubic-bezier(.2,.5,.5,1)',fill:'forwards'});}setTimeout(()=>wrap.remove(),3200);}

function setupSort(level){sortState={level,initial:createPuzzle(level),tubes:null,selected:null,history:[],moves:0,ended:false};sortState.tubes=sortState.initial.map(t=>[...t]);hudValue('#hud-score',level);hudValue('#hud-combo',fmt(data.best.sort));renderTubes();$('#sort-undo').onclick=undoSort;$('#sort-hint').onclick=hintSort;$('#sort-restart').onclick=()=>{showModal(`<h2 id="dialog-title">A fresh start?</h2><p>Restart this puzzle from its original arrangement.</p><button class="button" id="confirm-restart">Restart level</button><button class="button secondary" id="cancel-restart">Keep playing</button>`,()=>{});$('#confirm-restart').onclick=()=>{closeModal();sortState.tubes=sortState.initial.map(t=>[...t]);sortState.history=[];sortState.moves=0;sortState.selected=null;renderTubes();sound('tool');$('#game-message').textContent='A fresh start. Select a tube.';};$('#cancel-restart').onclick=closeModal;};}
function renderTubes(){const focused=document.activeElement?.dataset?.tube;const s=sortState;$('#sort-board').dataset.tubeCount=s.tubes.length;$('#sort-board').classList.toggle('many-tubes',s.tubes.length>5);$('#sort-board').classList.toggle('dense-tubes',s.tubes.length>6);$('#sort-board').innerHTML=s.tubes.map((t,i)=>`<button class="tube-button ${s.selected===i?'selected':''}" data-tube="${i}" aria-pressed="${s.selected===i}" aria-label="Tube ${i+1}: ${t.length?t.map(c=>COLOR_NAMES[c]).join(', ')+', bottom to top':'empty'}"><span class="tube"><span class="tube-fluid">${t.map(c=>`<span class="liquid" style="--c:${COLORS[c]}">${c+1}</span>`).join('')}</span></span><span class="tube-label">${i+1}</span></button>`).join('');const colors=[...new Set(s.tubes.flat())].sort();$('#sort-key').innerHTML=colors.map(c=>`<span><i style="--c:${COLORS[c]}"></i>${c+1} · ${COLOR_NAMES[c]}</span>`).join('');hudValue('#hud-detail',s.moves);$('#sort-undo').disabled=!s.history.length;app.querySelectorAll('[data-tube]').forEach(b=>b.onclick=()=>selectTube(Number(b.dataset.tube)));if(focused!==undefined)app.querySelector('[data-tube="'+focused+'"]')?.focus({preventScroll:true});}
function selectTube(index){const s=sortState;if(!s||s.ended||dialog.open)return;if(s.selected===null){if(!s.tubes[index].length){$('#game-message').textContent='Choose a tube with liquid first.';return;}s.selected=index;renderTubes();sound('select');$('#game-message').textContent=`Tube ${index+1} selected. Choose where to pour.`;return;}if(s.selected===index){s.selected=null;renderTubes();sound('undo');return;}const from=s.selected,next=pour(s.tubes,from,index);if(!next){sound('invalid');if(s.tubes[index].length===4)$('#game-message').textContent='That tube is full. Choose another or tap to deselect.';else $('#game-message').textContent='Pour onto the same colour, or into an empty tube.';return;}const pourColor=COLORS[s.tubes[from].at(-1)];s.history.push(s.tubes);s.tubes=next;s.moves++;s.selected=null;renderTubes();animatePour(from,index,pourColor);sound('drop');$('#game-message').textContent='A little closer. Lovely work.';if(isSolved(s.tubes)){s.ended=true;if($('#mission-fill'))$('#mission-fill').style.transform='scaleX(1)';sound('win');setTimeout(()=>{if(active==='sort'&&sortState===s)finishGame('sort',{score:Math.max(100,1200-s.moves*20),level:s.level,moves:s.moves,won:true});},350);}}
function animatePour(from,to,color){if(!motionAllowed())return;const a=$(`[data-tube="${from}"] .tube`),b=$(`[data-tube="${to}"] .tube`);const board=$('#sort-board'),bounds=board.getBoundingClientRect(),ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();const x1=ar.left-bounds.left+ar.width/2,y1=ar.top-bounds.top-5,x2=br.left-bounds.left+br.width/2,y2=br.top-bounds.top+12;const stream=document.createElementNS('http://www.w3.org/2000/svg','svg');stream.setAttribute('class','pour-stream');stream.setAttribute('viewBox',`0 0 ${bounds.width} ${bounds.height}`);stream.innerHTML=`<path d="M${x1} ${y1} Q${(x1+x2)/2} ${Math.min(y1,y2)-40} ${x2} ${y2}" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round" pathLength="100"/>`;board.append(stream);stream.animate([{opacity:0},{opacity:1,offset:.3},{opacity:0}],{duration:480});setTimeout(()=>stream.remove(),480);a?.animate([{transform:'translateY(-14px) rotate(0)'},{transform:`translateY(-20px) rotate(${to>from?25:-25}deg)`,offset:.4},{transform:'translateY(0) rotate(0)'}],{duration:460,easing:'cubic-bezier(.23,1,.32,1)'});b?.animate([{filter:'brightness(1)'},{filter:'brightness(1.3)',transform:'scale(1.06)',offset:.5},{filter:'brightness(1)',transform:'scale(1)'}],{duration:460});}

function undoSort(){if(!sortState.history.length||sortState.ended)return;sortState.tubes=sortState.history.pop();sortState.moves=Math.max(0,sortState.moves-1);sortState.selected=null;renderTubes();sound('undo');$('#game-message').textContent='One step back. Plenty of room to try again.';}
function hintSort(){if(sortState.ended)return;const move=findHint(sortState.tubes);if(move){sortState.selected=move[0];renderTubes();sound('hint');$('#game-message').textContent=`Try pouring tube ${move[0]+1} into tube ${move[1]+1}.`;}else{sound('invalid');$('#game-message').textContent='Try undoing a pour to free an empty tube. You can always restart.';}}
function stopGame(){clearHint();gameAudio.stop();loadTicket++;engine?.destroy();engine=null;active=null;sortState=null;}
function pauseGame(instructions=false){if(!active)return;engine?.pause();const id=active;showModal(`<div class="modal-emblem">${icon(instructions?'help':'leaf')}</div><h2 id="dialog-title">${instructions?games[id].name:'Take a little breath.'}</h2>${instructions?steps(id):'<p>Your game is right here when you’re ready.</p>'}<button class="button" id="resume-game">${icon('play')}Keep playing</button>${id!=='sort'?'<button class="button secondary" id="finish-run">Finish this run</button>':''}<button class="text-button" id="pause-instructions">${icon('help')}How to play</button><button class="button ghost" id="leave-game">Back to arcade</button>`,()=>engine?.pause(false));$('#resume-game').insertAdjacentHTML('beforebegin',soundSettingControl('pause-sound-setting'));bindSoundControl('pause-sound-setting');$('#resume-game').onclick=()=>{closeModal();engine?.pause(false);};if($('#finish-run'))$('#finish-run').onclick=()=>{closeModal();engine?.finish();};$('#pause-instructions').onclick=()=>pauseGame(true);$('#leave-game').onclick=()=>openLeave('freeplay');}
function openLeave(destination){engine?.pause();showModal(`<h2 id="dialog-title">Head back to the arcade?</h2><p>${active&&rankedRun(active)?'This run will end and the play is used. Choose Finish this run in the pause menu to keep your score.':'This run will end. You can start a fresh game whenever you like.'}</p><button class="button" id="confirm-leave">Back to ${destination==='journey'?'my journey':destination.startsWith('help')?'instructions':'arcade'}</button><button class="button secondary" id="cancel-leave">Keep playing</button>`,()=>engine?.pause(false));$('#confirm-leave').onclick=()=>{closeModal();route(destination);};$('#cancel-leave').onclick=()=>{closeModal();engine?.pause(false);};}
const RETRY_COIN_COST=50,DEMO_TOPUP=100;
function requestRetry(id,level){
 const retry=()=>{if(puzzleGames.includes(id))selectedPuzzle=id;beginGame(id,level);};
 if(data.coins>=RETRY_COIN_COST){data.coins-=RETRY_COIN_COST;save();retry();return;}
 const short=RETRY_COIN_COST-data.coins;
 showModal(`<div class="modal-emblem">${icon('coin')}</div><h2 id="dialog-title">A few more coins?</h2><p>A retry costs ${RETRY_COIN_COST} coins. Add ${DEMO_TOPUP} demo coins, then jump straight back in.</p><p class="demo-payment-note">Prototype top-up · no payment is taken.</p><button class="button gold-button" id="demo-topup">${icon('coin')}Add ${DEMO_TOPUP} demo coins</button><button class="button secondary" id="retry-later">Maybe later</button><span class="sr-only" id="retry-shortfall">${short} more coins needed</span>`);
 $('#demo-topup').onclick=()=>{data.coins+=DEMO_TOPUP;data.coins-=RETRY_COIN_COST;save();closeModal();toast(`${DEMO_TOPUP} demo coins added. ${RETRY_COIN_COST} spent on your retry.`);retry();};
 $('#retry-later').onclick=closeModal;
}
function finishGame(id,result){
 if(view==='result')return;
 const rankedMode=Boolean(rankedRun(id));
 if(window.parent!==window)window.parent.postMessage({type:'ph-game-finished',runId:rankedRun(id)?.runId,game:id,score:result.score,won:Boolean(result.won),level:runningLevel,replay:result.replay??null},location.origin);
 const playedLevel=runningLevel,puzzleLevelGame=puzzleGames.includes(id),endless=!puzzleLevelGame;
 result.level??=playedLevel;engine?.destroy();engine=null;active=null;view='result';data.games++;
 const previousBest=data.best[id]||0,newRecord=result.score>previousBest;data.best[id]=Math.max(previousBest,result.score);
 const day=localDay();if(!data.days.includes(day))data.days.push(day);
 if((id==='tower'&&result.height>0)||(id==='merge'&&result.merges>0)||(id==='sort'&&result.won)||(['blocks','mahjong','sequence'].includes(id)&&result.won))earn('first');
 if(id==='tower'){data.height=Math.max(data.height,result.height);data.perfects+=result.perfects;if(data.perfects>=5)earn('perfect5');if(result.height>=10)earn('tower10');}
 if(id==='merge'){data.tier=Math.max(data.tier,result.tier);if(result.tier>=5)earn('merge5');}
 if(id==='sort'&&result.won){data.sortWins++;data.sortLevel=Math.max(data.sortLevel,result.level+1);earn('sort1');}
 const won=puzzleLevelGame&&Boolean(result.won);
 const gained=won?5:0;data.xp+=gained;
 const loot=runLoot(data,won,false);data=loot.data;
 const runCoins=endless&&result.score>0?Math.min(30,5+Math.floor(result.score/300)*5):0;if(runCoins)data.coins+=runCoins;let dailyBonus=0;
 if(id==='merge'){if(data.mergeDay!==day){data.mergeDay=day;data.mergeToday=0;}data.mergeToday+=result.merges||0;if(data.mergeToday>=10&&!data.daily.includes(day)){data.daily.push(day);earn('daily');data.coins+=40;dailyBonus=40;}}
 if(won&&puzzleLevelGame)data.gameLevels[id]=Math.max(puzzleLevel(id),playedLevel+1);
 save();sound(won?'win':'miss');
 const title=won?'LEVEL CLEAR!':endless?'RUN OVER':'LEVEL NOT CLEARED';
 const status=won?`${games[id].name} · Level ${playedLevel}`:endless?(newRecord?'NEW PERSONAL BEST':'Personal best · '+fmt(data.best[id])):`${games[id].name} · Level ${playedLevel}`;
 const detailValue=id==='tower'?result.height:id==='merge'?result.merges:id==='mahjong'?result.pairs||playedLevel:id==='orbit'?result.orbits:id==='ridge'?result.gates:id==='bond'?result.bonds:result.moves||0;
 const detailLabel=id==='tower'?'Vials':id==='merge'?'Merges':id==='mahjong'?'Pairs':id==='orbit'?'Hoops':id==='ridge'?'Gates':id==='bond'?'Bonds':'Moves';
 const secondaryLabel=puzzleLevelGame?'Back to levels':'Choose another game';
 if(['blocks','ridge','sequence'].includes(id)){
  clearHint();rankedState=null;showReferenceResults({game:id,result,best:data.best[id],previousBest,level:playedLevel,motion:motionAllowed(),ranked:rankedMode?rankedResults(id,playedLevel):null,onReplay:()=>beginGame(id,won?playedLevel+1:playedLevel),onExit:()=>route('freeplay'),onRanks:()=>{if(window.parent!==window)window.parent.postMessage({type:'ph-game-ranks',game:id},location.origin);else route('freeplay');}});
  if(won)confetti();return;
 }
 shell(`<section class="result-screen ${won?'victory':'retry'} ${endless?'endless-result':''}"><div class="result-scene"><div class="victory-halo"></div><img src="assets/bottle-mascot.webp" alt="Your cheering bottle mascot"><span class="victory-medal">${icon(won?'trophy':endless?'star':'leaf')}</span><span class="result-star star-one">${icon('spark')}</span><span class="result-star star-two">${icon('spark')}</span></div><h1>${title}</h1><span class="result-status">${status}</span><p>${won?'Lovely work. The next puzzle is ready when you are.':endless?'Every run makes the next one more satisfying. Your best is saved on this device.':'You’re close. Spend coins to give this level another go.'}</p><div class="result-details"><div><strong>${fmt(result.score)}</strong><small>Score</small></div><div class="${newRecord?'record-stat':''}"><strong>${fmt(data.best[id])}</strong><small>${newRecord?'New best':'Personal best'}</small></div><div><strong>${fmt(detailValue)}</strong><small>${detailLabel}</small></div></div>${won&&puzzleLevelGame?`<div class="unlock-note">${icon('check')}Level ${playedLevel+1} unlocked. Keep your momentum.</div>`:''}<div class="result-loot">${icon('coin')} +${fmt(loot.coins+runCoins+dailyBonus)} coins${loot.gems?` ${icon('gem')} +${loot.gems} gem`:''}</div><div class="result-actions"><button class="button" id="result-continue">${icon(won?'arrow':'restart')}${won?'Next level':`Retry · ${RETRY_COIN_COST} coins`}</button><button class="button secondary" id="result-home">${secondaryLabel}</button></div></section>`,'game',id);
 $('#result-continue').onclick=()=>{if(won&&puzzleLevelGame){beginGame(id,playedLevel+1);}else requestRetry(id,playedLevel);};
 if(rankedMode){const next=$('#result-continue'),text=$('.result-screen > p');if(text)text.textContent=won&&id==='sequence'?'Level cleared. Keep going: every level you clear adds to this run.':'Your score is being checked for the leaderboard.';
  if(won&&id==='sequence')next.onclick=async()=>{next.disabled=true;next.lastChild.textContent=' Checking…';if(await rankedNextLevel(id,playedLevel+1))beginGame(id,playedLevel+1);else{toast('This run could not continue. Your verified score still counts.');route('freeplay');}};
  else{next.innerHTML=`${icon('arrow')}Back to Play`;next.onclick=()=>route('freeplay');}}
 $('#result-home').onclick=()=>route(puzzleLevelGame?'arcade':'freeplay');
 if(won)confetti();
}

window.addEventListener('keydown',e=>{if(dialog.open||!active)return;if(e.key==='Escape'){e.preventDefault();pauseGame();return;}if(!engine||e.target.closest('button,input,a'))return;if(active==='orbit'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();engine.aim(e.key);return;}if(active==='sequence'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();engine.moveSelection(e.key);return;}if(e.code==='Space'||e.key==='Enter'){e.preventDefault();engine.action?.();}if(active==='merge'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();engine.move(e.key==='ArrowLeft'?-1:1);}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){gameAudio.stop();if(active&&!dialog.open)pauseGame();}});
window.addEventListener('hashchange',()=>route(location.hash.slice(1)||'home'));
route(location.hash.slice(1)||'home');
